"""Build the bounded final B2 review: corrections, four proposal batches, last 16."""
from pathlib import Path
import html,json,re,os
from build_b2_analysis_review import SvgRenderer
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'design/icon-set-b2'
AUDIT=ROOT/'harmonization/icon-set-b2'
def esc(value):return html.escape(str(value),quote=True)
def build():
    report=json.loads((AUDIT/'final-review-104.json').read_text(encoding='utf8'))
    renderer=SvgRenderer();cards=[]
    labels={'corrected':'Aangepast','proposed':'Voorstel','retain':'Behouden'}
    for row in report['icons']:
        decision=row['decision'];samples=''
        badge='Goedgekeurd' if row.get('user_approved') else labels[decision]
        states=[('after','Huidig'),('proposal','Getekend voorstel')] if decision=='proposed' else [('before','Voor'),('after','Nu')] if row['changed'] else [('after','Beoordeeld ontwerp')]
        for state,label in states:samples+='<div><h3>'+label+'</h3>'+renderer.sample(row,state)+'</div>'
        source=row['source'];hashes=' · '.join(f'{n}px: <code>{esc(v["after_sha256"])}</code>' for n,v in row['assets'].items())
        status='<p class="proposal-note">Afzonderlijk voorstel; nog niet toegepast.</p>' if decision=='proposed' else ''
        cards.append(f'<article id="icon-{esc(row["id"])}" data-batch="{esc(row["batch"])}" data-search="{esc((row["label"]+" "+row["id"]+" "+row["finding"]).lower())}"><span class="badge {decision}">{badge}</span><h2>{esc(row["label"])}</h2><code>{esc(row["id"])}</code><div class="comparison {"single" if len(states)==1 else ""}">{samples}</div>{status}<p><strong>Beoordeling:</strong> {esc(row["finding"])}</p><p><strong>Uitwerking:</strong> {esc(row["action"])}</p><details><summary>Functie, bron en controle</summary><p>{esc(row["ui_call"])}</p><a href="{esc(source["source_url"])}">{esc(source["app"])} · {esc(source["path"])}:{source["line"]}</a><p>Broncommit: <code>{esc(source["commit"])}</code></p><p>{hashes}</p></details></article>')
    tabs=[('corrections','37 correcties')]+[(f'proposals-{n}',f'Voorstellen {n} · 16') for n in range(1,5)]+[('last','Laatste 16'),('all','Alles')]
    buttons=''.join(f'<button data-batch="{key}">{label}</button>' for key,label in tabs)
    css='''<style>:root{color-scheme:dark;--bg:#28282e;--panel:#323239;--ink:#ebebeb;--muted:#c1c1c8;--line:#818187;--icon-accent:#ed8c00}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,sans-serif}body.light{color-scheme:light;--bg:#f4f4f4;--panel:#fff;--ink:#202020;--muted:#555;--line:#999;--icon-accent:#a55400}body.mono{--icon-accent:var(--ink)}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:27px;margin:0 0 12px}h2{font-size:17px;margin:10px 0 3px}h3{font-size:12px;color:var(--muted);font-weight:500;margin:0}a{color:inherit;text-underline-offset:3px}.lead{max-width:1050px}.controls{position:sticky;top:0;background:var(--bg);z-index:2;padding:12px 0;display:flex;gap:8px;flex-wrap:wrap;border-bottom:1px solid var(--line)}button,input,select{font:inherit;color:inherit;background:var(--panel);border:1px solid var(--line);border-radius:5px;padding:8px}button{cursor:pointer}button[aria-pressed=true]{outline:2px solid var(--icon-accent);outline-offset:1px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(400px,100%),1fr));gap:16px;align-items:start}article{padding:18px;border:1px solid var(--line);background:var(--panel);border-radius:10px;scroll-margin-top:180px}article:target{outline:3px solid var(--icon-accent)}.badge{font-size:11px;border:1px solid var(--line);border-radius:4px;padding:2px 7px}.proposed{border-color:var(--icon-accent)}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:18px 0}.single{grid-template-columns:1fr}.hero{height:80px;display:flex;align-items:center;justify-content:center}.native{height:63px;display:flex;align-items:end;justify-content:center;gap:22px}.native span{display:flex;flex-direction:column;align-items:center;gap:5px}.native small{font-size:10px;color:var(--muted)}code{font:11px ui-monospace,monospace;overflow-wrap:anywhere}details{margin:14px 0}summary{cursor:pointer}.proposal-note{color:var(--muted);font-size:12px}[hidden]{display:none!important}:focus-visible{outline:3px solid var(--icon-accent);outline-offset:3px}@media(max-width:600px){main{padding:14px}.controls{position:static}}</style>'''
    script='''<script>const cards=[...document.querySelectorAll('article[data-batch]')],search=document.getElementById('search'),buttons=[...document.querySelectorAll('button[data-batch]')];let batch=new URLSearchParams(location.search).get('batch')||'corrections';if(!buttons.some(b=>b.dataset.batch===batch))batch='corrections';const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target)batch=target.dataset.batch;function render(){let count=0,q=search.value.toLocaleLowerCase('nl');for(const card of cards){card.hidden=(batch!=='all'&&card.dataset.batch!==batch)||!card.dataset.search.includes(q);if(!card.hidden)count++}for(const button of buttons)button.setAttribute('aria-pressed',String(button.dataset.batch===batch));document.getElementById('count').textContent=count+' van '+cards.length+' ontwerpen zichtbaar'}for(const button of buttons)button.onclick=()=>{batch=button.dataset.batch;render()};search.oninput=render;document.getElementById('theme').onchange=e=>document.body.classList.toggle('light',e.target.value==='light');document.getElementById('mono').onchange=e=>document.body.classList.toggle('mono',e.target.checked);render();if(target)requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));</script>'''
    doc=f'<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laatste B2-icoonronde</title>{css}<main><h1>Laatste B2-icoonronde</h1><div class="lead"><p><strong>37 recente correcties nagekeken, 64 voorstellen in vier groepen beoordeeld en de laatste 16 ontwerpen geanalyseerd.</strong> De steeksleutel is al door jou goedgekeurd. De 64 getekende alternatieven blijven apart voor jouw keuze.</p><p>Deze ronde: 10 gebruikte ontwerpen aangepast, waaronder het relatie-icoon en negen van de laatste 16; zeven van die 16 behouden. Tien voorstellen zijn verder uitgewerkt. Alle concrete bronfuncties en hashes staan bij het ontwerp.</p><p><a href="feedback-overview.html">Jouw feedback</a> · <a href="analysis-review-104.html?filter=all">Analyse laatste 16</a> · <a href="completion-review.html">Volledige set van 945 ontwerpen</a></p></div><div class="controls">{buttons}<input id="search" type="search" aria-label="Zoek icoon" placeholder="Zoek icoon"><select id="theme" aria-label="Thema"><option value="dark">Donker</option><option value="light">Licht</option></select><label><input id="mono" type="checkbox"> Eén kleur</label></div><p id="count" role="status"></p><section class="grid">'+''.join(cards)+f'</section><p>Revisie {report["revision"]} · ontwerp- en reviewmateriaal · bibliotheek- en appintegratie volgen afzonderlijk.</p></main>{script}</html>'
    pending=sum(row['decision']=='proposed' for row in report['icons'])
    doc=doc.replace('De 64 getekende alternatieven blijven apart voor jouw keuze.',f'Nog {pending} getekende alternatieven wachten op jouw keuze. Vastgelegde keuzes staan op hun eigen kaart.')
    if report['summary'].get('applied_proposals'):
        doc=doc.replace(f'Nog {pending} getekende alternatieven wachten op jouw keuze. Vastgelegde keuzes staan op hun eigen kaart.','Alle 61 resterende voorstellen zijn op jouw akkoord toegepast. RAW en IBIS blijven huidig; Bouw 1 behoudt het hertekende huisje. Alleen het vierkant bij Platform synchroniseren is daarna nog hersteld.')
        doc=doc.replace('Deze ronde: 10 gebruikte ontwerpen aangepast, waaronder het relatie-icoon en negen van de laatste 16; zeven van die 16 behouden. Tien voorstellen zijn verder uitgewerkt.','Slotronde: 61 goedgekeurde alternatieven toegepast en het vierkant rechtsboven bij Platform synchroniseren gecorrigeerd.')
    target=OUT/'final-review-104.html';temp=target.with_suffix('.html.tmp');temp.write_text(doc,encoding='utf8',newline='\n');os.replace(temp,target)
    print(f'{len(cards)} kaarten; vier groepen van 16; {target.stat().st_size} bytes.')
if __name__=='__main__':build()
